public class ContactTriggerHandler {

    // Guard so a single transaction's before/after contexts run the logic once,
    // and so account updates don't re-enter this trigger recursively.
    private static Boolean executing = false;

    public static void run() {
        if (!executing) {
            executing = true;

            Map<Id, Account> accounts = queryAccounts();

            if (Trigger.isBefore) {
                beforeProcess(accounts);
            }

            if (Trigger.isAfter && Trigger.isInsert) {
                afterProcess(accounts);
            }

            executing = false;
        }
    }

    // Single SOQL query covering every account referenced by the trigger batch.
    private static Map<Id, Account> queryAccounts() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        Map<Id, Account> accounts = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            accounts.putAll([
                SELECT Id, BillingCountry, AccountSource, Phone
                FROM Account
                WHERE Id IN :accountIds
            ]);
        }
        return accounts;
    }

    private static void beforeProcess(Map<Id, Account> accounts) {
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                Account a = accounts.get(c.AccountId);
                if (String.isBlank(c.MailingCountry) && a != null) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (Trigger.isInsert && String.isBlank(c.LeadSource) && a != null) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    private static void afterProcess(Map<Id, Account> accounts) {
        // Preserve original behaviour: the first contact in trigger order that has
        // a phone wins when the account has no phone at the start of the transaction.
        Map<Id, String> firstContactPhoneByAccountId = new Map<Id, String>();

        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                Account a = accounts.get(c.AccountId);
                if (a != null
                        && String.isBlank(a.Phone)
                        && !firstContactPhoneByAccountId.containsKey(c.AccountId)) {
                    firstContactPhoneByAccountId.put(c.AccountId, c.Phone);
                }
            }
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : firstContactPhoneByAccountId.keySet()) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                Phone = firstContactPhoneByAccountId.get(accountId)
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate; // single DML statement
        }
    }
}
