public inherited sharing class RecordSearchService {

    public class SearchException extends Exception {}

    // Bounds on LIMIT to keep the service safe and predictable.
    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---------- 1. Validate maxRows (throw SearchException, never anything else) ----------
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.');
        }

        // ---------- 2. Validate fields ----------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // ---------- 3. Resolve and validate the object (existence + user readability) ----------
        String objectDescribeKey = normalize(objectApiName);
        Schema.SObjectType sObjectType = Schema.getGlobalDescribe().get(objectDescribeKey);
        if (sObjectType == null) {
            throw new SearchException('Object does not exist or is not accessible: ' + objectApiName);
        }
        Schema.DescribeSObjectResult describe = sObjectType.getDescribe(SObjectDescribeOptions.DEFERRED);
        if (!describe.isQueryable()) {
            throw new SearchException('Running user cannot read the object: ' + objectApiName);
        }
        String actualObjectName = describe.getName();

        // Field describe maps for the resolved object.
        Map<String, Schema.SObjectField> fieldMap = describe.fields.getMap();
        if (fieldMap == null) {
            throw new SearchException('Unable to describe fields for object: ' + objectApiName);
        }

        // ---------- 4. Validate requested fields (existence + readability + Id handling) ----------
        // Always select Id (per spec: "SELECT Id plus the requested fields").
        // Using a Set keeps the query valid if a caller requests 'Id' explicitly.
        Set<String> selectFields = new Set<String>{ 'Id' };
        for (String requested : fields) {
            String key = normalize(requested);
            Schema.SObjectField token = fieldMap.get(key);
            if (token == null) {
                throw new SearchException('Field does not exist on ' + actualObjectName + ': ' + requested);
            }
            Schema.DescribeFieldResult fieldDescribe = token.getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('Running user cannot read field: ' + requested);
            }
            // Store the actual (correctly cased) API name for the query.
            selectFields.add(fieldDescribe.getName());
        }

        // ---------- 5. Validate order-by field (existence + sortability + readability) ----------
        String orderByClauseField;
        if (String.isNotBlank(orderByField)) {
            String orderByKey = normalize(orderByField);
            Schema.SObjectField orderByToken = fieldMap.get(orderByKey);
            if (orderByToken == null) {
                throw new SearchException('Order-by field does not exist on ' + actualObjectName + ': ' + orderByField);
            }
            Schema.DescribeFieldResult orderByDescribe = orderByToken.getDescribe();
            if (!orderByDescribe.isSortable() || !orderByDescribe.isAccessible()) {
                throw new SearchException('Field cannot be used in ORDER BY: ' + orderByField);
            }
            orderByClauseField = orderByDescribe.getName();
        }

        // ---------- 6. Build the WHERE clause from the filters ----------
        // Values are never string-concatenated: they go into bind variables, so SOQL
        // injection via filter values is impossible. Keys must still be validated
        // against the describe because they end up in the query text.
        String whereClause = '';
        Map<String, Object> bindVariables = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            Integer bindIndex = 0;
            for (String filterKey : filters.keySet()) {
                String fieldKey = normalize(filterKey);
                Schema.SObjectField filterToken = fieldMap.get(fieldKey);
                if (filterToken == null) {
                    throw new SearchException('Filter field does not exist on ' + actualObjectName + ': ' + filterKey);
                }
                Schema.DescribeFieldResult filterDescribe = filterToken.getDescribe();
                if (!filterDescribe.isFilterable() || !filterDescribe.isAccessible()) {
                    throw new SearchException('Field cannot be used in a filter: ' + filterKey);
                }

                // Distinct bind variable per filter; the value itself is never inlined.
                String bindName = 'filterVal' + bindIndex;
                bindVariables.put(bindName, filters.get(filterKey));
                conditions.add(filterDescribe.getName() + ' = :' + bindName);
                bindIndex++;
            }
            whereClause = ' WHERE ' + String.join(conditions, ' AND ');
        }

        // ---------- 7. Assemble and run the single query ----------
        String soql = 'SELECT '
            + String.join(new List<String>(selectFields), ', ')
            + ' FROM ' + actualObjectName
            + whereClause;
        if (orderByClauseField != null) {
            soql += ' ORDER BY ' + orderByClauseField + ' ASC NULLS LAST';
        }
        soql += ' LIMIT :maxRows';

        try {
            return Database.query(soql, bindVariables);
        } catch (Exception e) {
            // Defensive: surface any runtime SOQL failure as SearchException so
            // callers never receive another exception type from this service.
            throw new SearchException('Query execution failed: ' + e.getMessage());
        }
    }

    // Lower-cased helper: global describe keys and field-map keys are lowercase.
    private static String normalize(String name) {
        return name == null ? '' : name.trim().toLowerCase();
    }
}
