public inherited sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true label='Email')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing contact by email (case-insensitive, trimmed). Returns the oldest contact when multiple match.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Collect trimmed, lowercased emails; remember result position of each.
        Map<String, Integer> emailToIndex = new Map<String, Integer>();
        List<String> lookupEmails = new List<String>();
        for (Integer i = 0; i < requests.size(); i++) {
            String trimmed = requests[i].email == null ? null : requests[i].email.trim();
            String normalized = String.isBlank(trimmed) ? null : trimmed.toLowerCase();

            if (normalized == null) {
                results.add(blankResult());
                continue;
            }

            // Deduplicate: same email in the batch reuses one result object.
            if (emailToIndex.containsKey(normalized)) {
                Integer existingIndex = emailToIndex.get(normalized);
                results.add(results[existingIndex]);
                continue;
            }

            emailToIndex.put(normalized, results.size());
            results.add(blankResult()); // placeholder; filled after query
            lookupEmails.add(normalized);
        }

        if (!lookupEmails.isEmpty()) {
            // One SOQL query per call, with bind variables (safe from SOQL injection).
            // Order by CreatedDate ascending so the earliest-created contact per email
            // is captured first. WITH USER_MODE enforces the running user's sharing
            // (and CRUD/FLS) on the query.
            Map<String, Contact> oldestByEmail = new Map<String, Contact>();
            List<Contact> contacts = [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :lookupEmails
                ORDER BY CreatedDate ASC
                WITH USER_MODE
            ];
            for (Contact c : contacts) {
                String normalizedEmail = c.Email == null ? null : c.Email.trim().toLowerCase();
                if (normalizedEmail != null && !oldestByEmail.containsKey(normalizedEmail)) {
                    oldestByEmail.put(normalizedEmail, c);
                }
            }

            for (String normalizedEmail : emailToIndex.keySet()) {
                Integer resultIndex = emailToIndex.get(normalizedEmail);
                Contact c = oldestByEmail.get(normalizedEmail);
                if (c != null) {
                    results[resultIndex].contactId = c.Id;
                    results[resultIndex].found = true;
                }
            }
        }

        return results;
    }

    private static Result blankResult() {
        Result r = new Result();
        r.contactId = null;
        r.found = false;
        return r;
    }
}
