public inherited sharing PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        Schema.DescribeSObjectResult objectDescribe;
        try {
            List<Schema.DescribeSObjectResult> results =
                Schema.describeSObjects(new List<String>{ objectApiName });
            objectDescribe = results[0];
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Object does not exist: ' + objectApiName, e);
        }

        Map<String, Schema.SObjectField> fields = objectDescribe.fields.getMap();
        String key = fieldApiName.toLowerCase();
        if (!fields.containsKey(key)) {
            throw new PicklistServiceException(
                'Field does not exist on object ' + objectDescribe.getName() + ': ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = fields.get(key).getDescribe();
        if (!fieldDescribe.isPicklist()) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
        List<Option> options = new List<Option>();

        for (Schema.PicklistEntry entry : entries) {
            Option option = new Option();
            option.value = (String) entry.getValue();
            option.label = (String) entry.getLabel();
            option.isDefault = false;
            options.add(option);
        }

        String defaultValueName = '';
        for (Schema.PicklistValueInfo info : fieldDescribe.getPicklistValues()) {
            if (info.isDefaultValue()) {
                defaultValueName = info.getValue();
                break;
            }
        }

        if (String.isNotBlank(defaultValueName)) {
            for (Option option : options) {
                option.isDefault = option.value == defaultValueName;
            }
        }

        return options;
    }
}
