public without sharing class AccountOnboardingService {

    /**
     * Creates one Account per map key and, for each entry value, one Contact with that
     * LastName under the newly created account. All work is registered in a single
     * fflib_SObjectUnitOfWork and committed once via commitWork(); no DML is performed here.
     *
     * @param contactLastNamesByAccountName map of Account.Name -> list of Contact.LastName values
     * @return the newly inserted Accounts, with Ids populated (empty list for null/empty input)
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<SObjectType> {
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        // "Account Name" -> the Account record registered in the UoW.
        // Contacts are registered against the same in-memory Account instance,
        // so the UoW resolves the foreign key when the accounts are inserted
        // during the single commitWork() call.
        Map<String, Account> accountsByName = new Map<String, Account>();
        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            if (accountName == null) {
                continue;
            }

            Account account = new Account(Name = accountName);
            accountsByName.put(accountName, account);
            newAccounts.add(account);
            uow.registerNew(account);
        }

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            if (accountName == null) {
                continue;
            }

            Account account = accountsByName.get(accountName);
            List<String> lastNames = contactLastNamesByAccountName.get(accountName);

            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                if (String.isBlank(lastName)) {
                    continue;
                }

                uow.registerNew(new Contact(
                    LastName = lastName,
                    AccountId = account.Id
                ));
            }
        }

        uow.commitWork();

        // commitWork() populates the Ids on the inserted accounts; return them
        // in map-key order so callers get a deterministic result.
        return newAccounts;
    }
}
