public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e platform event per Opportunity.
     *
     * Events are published one at a time with EventBus.publish inside the loop so each
     * event's own SaveResult is captured; results are returned in the same order as the
     * input list. Note that publish-after-commit events are enqueued here but are only
     * delivered to subscribers after the enclosing transaction commits.
     *
     * @param opportunities the Opportunities to publish events for; may be null or empty
     * @return the EventBus publish results, in the same order as the input list
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        // Guard: nothing to publish, and EventBus.publish(null) is not safe.
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e event = new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c = opp.StageName,
                Amount__c = opp.Amount
            );
            results.add(EventBus.publish(event));
        }

        return results;
    }
}
