     * product unless the rep typed a discount in (including 0).
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        Map<Id, Product2> productsById = productIds.isEmpty()
            ? new Map<Id, Product2>()
            : new Map<Id, Product2>([
                SELECT Id, Family
                FROM Product2
                WHERE Id IN :productIds
            ]);

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null) {
                if (line.Product2Id == null) {
                    line.Discount = PricingRules.standardDiscountForFamily(null);
                } else if (productsById.containsKey(line.Product2Id)) {
                    line.Discount = PricingRules.standardDiscountForFamily(
                        productsById.get(line.Product2Id).Family
                    );
                } else {
                    // Product not present in the org data; treat as no family.
                    line.Discount = PricingRules.standardDiscountForFamily(null);
                }
            }
        }
    }
