```javascript
import { LightningElement, api } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];

    // Monotonic counter: a response may only be applied if it belongs to
    // the most recently issued request (and the component is still alive).
    requestSequence = 0;
    debounceTimerId;

    connectedCallback() {
        this.contacts = [];
    }

    disconnectedCallback() {
        // Stop any pending debounced search from firing after removal.
        this.clearDebounceTimer();
        // Invalidate any in-flight request so its response is ignored.
        this.requestSequence++;
        this.contacts = [];
    }

    handleSearchChange(event) {
        this.searchTerm = event.target.value;
        this.clearDebounceTimer();

        const trimmed = (this.searchTerm || '').trim();

        // Too short: cancel pending search, do not call Apex, clear results.
        if (trimmed.length < MIN_SEARCH_LENGTH) {
            this.clearResults();
            return;
        }

        // Debounce: only search once the user stopped typing for 300 ms.
        this.debounceTimerId = setTimeout(() => {
            this.debounceTimerId = undefined;
            this.executeSearch(trimmed);
        }, DEBOUNCE_DELAY_MS);
    }

    executeSearch(trimmedSearchTerm) {
        const sequence = ++this.requestSequence;

        searchContacts({ searchTerm: trimmedSearchTerm })
            .then((result) => {
                // Out-of-order protection and post-disconnect protection:
                // only the most recent request may update the results.
                if (sequence !== this.requestSequence) {
                    return;
                }
                this.contacts = result || [];
            })
            .catch((error) => {
                if (sequence !== this.requestSequence) {
                    return;
                }
                this.contacts = [];
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    'An unknown error occurred.';
            });
    }

    clearResults() {
        this.contacts = [];
        this.errorMessage = '';
    }

    clearDebounceTimer() {
        if (this.debounceTimerId !== undefined) {
            clearTimeout(this.debounceTimerId);
            this.debounceTimerId = undefined;
        }
    }
}
