import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

const STATE = {
    LOADING: 'loading',
    DATA: 'data',
    ERROR: 'error'
};

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    state = STATE.LOADING;
    opportunities = [];
    errorMessage;

    get isLoading() {
        return this.state === STATE.LOADING;
    }

    get hasData() {
        return this.state === STATE.DATA;
    }

    get hasError() {
        return this.state === STATE.ERROR;
    }

    get isListEmpty() {
        return !this.opportunities.length;
    }

    get hasOpportunities() {
        return this.opportunities.length > 0;
    }

    connectedCallback() {
        this.loadOpportunities();
    }

    async loadOpportunities() {
        this.state = STATE.LOADING;
        try {
            const result = await getOpenOpportunities({ accountId: this.recordId });
            this.opportunities = result ?? [];
            this.state = STATE.DATA;
        } catch (error) {
            this.errorMessage = error?.body?.message ?? 'Unknown error';
            this.state = STATE.ERROR;
        }
    }

    handleRetry() {
        this.loadOpportunities();
    }
}
