public with sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';
    private static final String STATUS_FORMER = 'Former';
    private static final Date TODAY = Date.today();

    /**
     * Sets each contact's current employer via NPSP's standard affiliation mechanism.
     * Null/empty map does nothing. Max 2 SOQL + 2 DML.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Normalize: unique contact -> org pairs, skipping null/invalid keys & values.
        Map<Id, Id> pairs = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            if (contactId == null) {
                continue;
            }
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }
            try {
                if (!contactId.getSObjectType().equals(Contact.SObjectType)
                        || !orgId.getSObjectType().equals(Account.SObjectType)) {
                    continue;
                }
            } catch (System.TypeException e) {
                continue;
            }
            pairs.put(contactId, orgId);
        }
        if (pairs.isEmpty()) {
            return;
        }

        // Query 1: contacts with their current primary affiliation account.
        Map<Id, Contact> contactsById = new Map<Id, Contact>(
            [SELECT Id, npsp__Primary_Affiliation__c
             FROM Contact
             WHERE Id IN :pairs.keySet()]
        );

        // Query 2: existing affiliations between those contacts and those orgs.
        Map<String, npe5__Affiliation__c> existingByKey = new Map<String, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c, npe5__StartDate__c, npe5__EndDate__c, npe5__Role__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :pairs.keySet()
              AND npe5__Organization__c IN :pairs.values()
        ]) {
            existingByKey.put(aff.npe5__Contact__c, aff);
        }

        // Affiliations to make Current + primary (trigger the NPSP mechanism).
        List<npe5__Affiliation__c> upsertList = new List<npe5__Affiliation__c>();
        // Affiliations to force to Former/non-primary/EndDate today.
        List<npe5__Affiliation__c> toEnd = new List<npe5__Affiliation__c>();

        for (Id contactId : pairs.keySet()) {
            Id orgId = pairs.get(contactId);
            Contact c = contactsById.get(contactId);
            npe5__Affiliation__c existing = existingByKey.get(contactId);

            if (existing != null
                    && existing.npe5__Organization__c == orgId
                    && existing.npe5__Status__c == STATUS_CURRENT
                    && existing.npe5__Primary__c) {
                // Already the current primary employer: nothing to do.
                continue;
            }

            if (existing != null) {
                // Reuse the existing affiliation record to this org.
                existing.npe5__Status__c = STATUS_CURRENT;
                existing.npe5__Primary__c = true;
                existing.npe5__EndDate__c = null;
                if (existing.npe5__StartDate__c == null) {
                    existing.npe5__StartDate__c = TODAY;
                }
                upsertList.add(existing);
            } else {
                // Create a new Current primary affiliation; NPSP's standard mechanism
                // sets Contact.npsp__Primary_Affiliation__c and ends any previous
                // primary affiliation as Former with EndDate = today.
                upsertList.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = STATUS_CURRENT,
                    npe5__Primary__c = true,
                    npe5__StartDate__c = TODAY,
                    npe5__Role__c = 'Current Employer'
                ));
            }
        }

        if (!upsertList.isEmpty()) {
            insert upsertList;
        }
        if (!toEnd.isEmpty()) {
            update toEnd;
        }
    }
}
