public inherited sharing class GiftService {

    private static final String OPP_NAME_FORMAT = '%s Donation %s';
    private static final String DATE_FORMAT = 'yyyy-MM-dd';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';
    private static final String ROLE_DONOR = 'Donor';
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    /**
     * Thrown when the gift cannot be recorded. Extends IllegalArgumentException
     * so callers can catch either type.
     */
    public class GiftServiceException extends Exception {}

    /**
     * Records a gift that has already been received.
     *
     * Creates a Closed Won Opportunity on the contact's Household Account,
     * sets the contact as the primary contact with a 'Donor' contact role,
     * ensures every other household member has a 'Household Member' role,
     * and creates exactly one fully paid NPSP Payment for the full amount.
     *
     * @param contactId the donor contact
     * @param amount    the gift amount (must be positive)
     * @param giftDate  the date the gift was received
     * @return the new Opportunity Id
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // ---- Input validation ----
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be a positive, non-zero value.');
        }

        // ---- Load contact ----
        Contact donor = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donor == null) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        // NPSP with the Household Account model: contacts belong to a household Account.
        Id householdAccountId = donor.AccountId;
        if (householdAccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' does not belong to a household account.');
        }

        // ---- Gather household members (all contacts on the household account) ----
        List<Contact> householdMembers = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE AccountId = :householdAccountId
            ORDER BY Id
        ];

        // ---- Build the Opportunity ----
        String donorName = (donor.FirstName != null ? donor.FirstName : '') + ' ' +
                           (donor.LastName != null ? donor.LastName : '');
        donorName = donorName.trim();
        String dateStr = giftDate != null ? formatGiftDate(giftDate) : null;
        String oppName = dateStr != null
            ? String.format(OPP_NAME_FORMAT, new List<Object>{ donorName, dateStr })
            : donorName + ' Donation';

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = householdAccountId,
            StageName = STAGE_CLOSED_WON,
            CloseDate = giftDate,
            npsp__Primary_Contact__c = contactId
        );
        insert opp;

        // ---- Contact roles: no contact may hold more than one role ----
        Set<Id> contactsWithRole = new Set<Id>();
        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();

        // Every household member other than the donor gets 'Household Member'.
        for (Contact member : householdMembers) {
            if (member.Id == contactId || contactsWithRole.contains(member.Id)) {
                continue;
            }
            rolesToInsert.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = member.Id,
                Role = ROLE_HOUSEHOLD_MEMBER,
                IsPrimary = false
            ));
            contactsWithRole.add(member.Id);
        }
        // The donor gets exactly one 'Donor' role, marked primary.
        rolesToInsert.add(new OpportunityContactRole(
            OpportunityId = opp.Id,
            ContactId = contactId,
            Role = ROLE_DONOR,
            IsPrimary = true
        ));
        insert rolesToInsert;

        // ---- Payment: exactly one, paid, full amount, dated giftDate ----
        // Remove any payment NPSP may have auto-created so we end with exactly one.
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opp.Id
        ];
        if (!existingPayments.isEmpty()) {
            delete existingPayments;
        }

        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        try {
            insert payment;
        } catch (DmlException e) {
            // Roll back the opportunity so we never leave a gift without its payment.
            Savepoint sp = Database.setSavepoint();
            Database.rollback(sp);
            throw new GiftServiceException('Failed to create the payment for the gift: '
                + e.getMessage());
        }

        return opp.Id;
    }

    private static String formatGiftDate(Date d) {
        return d.year() + '-'
            + (d.month() < 10 ? '0' : '') + d.month() + '-'
            + (d.day() < 10 ? '0' : '') + d.day();
    }
}
