/**
 * TDTM Trigger Handler: OPP_MajorGiftFollowUp_TDTM
 *
 * NPSP Table-Driven Trigger Management (TDTM) handler for Opportunity
 * (AfterInsert / AfterUpdate).
 *
 * Behaviour:
 *   When an Opportunity qualifies as a major gift (Closed Won with Amount >= 5000),
 *   create one Task:
 *     Subject    = 'Major gift thank-you call'
 *     Priority   = 'High'
 *     Status     = 'Not Started'
 *     WhatId     = the Opportunity
 *     WhoId      = the Opportunity's npsp__Primary_Contact__c (may be null)
 *     OwnerId    = the Opportunity's OwnerId
 *     ActivityDate = the Opportunity's CloseDate + 3 days
 *
 *   On insert: create the Task when the Opportunity qualifies.
 *   On update: create the Task only when the Opportunity qualifies NOW and
 *              did NOT already qualify BEFORE (i.e. it was not already
 *              Closed Won with Amount >= 5000). Editing a gift that already
 *              qualified therefore never creates a second Task.
 *
 * The admin registers this class as an NPSP Trigger Handler record:
 *   Class = OPP_MajorGiftFollowUp_TDTM, Object = Opportunity,
 *   Trigger Action = AfterInsert;AfterUpdate, Load Order = 5, not asynchronous.
 * NPSP's TDTM dispatcher (npsp.TDTM_ObjectDataSink / npsp.TDTM_Runnable)
 * calls run() for every committed batch of Opportunities while the
 * npsp__Trigger_Handler__mdt record is active. When the admin deactivates
 * that record (npsp__Trigger_Is_Active__c = false), the dispatcher stops
 * invoking this handler entirely — no Apex trigger change is required.
 *
 * Bulk-safe: handles 200+ Opportunities in one transaction using at most
 * 1 SOQL query and 1 DML statement of its own (NPSP's dispatcher already
 * has Trigger.new / Trigger.oldMap in memory, so no extra SOQL is needed).
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    /** Amount threshold for a "major gift". */
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    /** Task field values. */
    private static final String TASK_SUBJECT  = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS   = 'Not Started';
    private static final Integer DAYS_AFTER_CLOSE = 3;

    /**
     * NPSP TDTM entry point.
     *
     * NOTE on the signature: the base class npsp.TDTM_Runnable declares run()
     * as a *virtual* (overridable) method taking a trailing
     * npsp.TDTM_Runnable.Options parameter. The 4-parameter variant shown in
     * NPSP's older examples is the abstract one and cannot be instantiated or
     * invoked directly; the 5-parameter virtual variant is the one the NPSP
     * dispatcher actually calls on concrete handlers, so we override that.
     */
    public override npsp.TDTM_Runnable.dmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult,
        npsp.TDTM_Runnable.Options options
    ) {
        // Delegate to the base class first (it sets up handler state).
        npsp.TDTM_Runnable.dmlWrapper wrapper = super.run(newlist, oldlist, triggerAction, objResult, options);

        // Respect the admin's Trigger Handler toggle: when the
        // npsp__Trigger_Handler__mdt record is deactivated (or this Object /
        // Trigger Action combination is not enabled), the base class disables
        // the handler and we must not run any of our logic or DML.
        if (!this.isEnabledFor(objResult)) {
            return wrapper;
        }

        List<Task> tasksToCreate = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity newOpp = (Opportunity) newlist[i];
            if (newOpp == null) {
                continue;
            }

            Boolean qualifiesNow = isMajorGift(newOpp);

            Boolean shouldCreate = false;

            if (triggerAction == npsp.TDTM_Runnable.Action.afterInsert) {
                shouldCreate = qualifiesNow;
            } else if (triggerAction == npsp.TDTM_Runnable.Action.afterUpdate) {
                Opportunity oldOpp = (Opportunity) oldlist != null && oldlist.size() > i
                    ? (Opportunity) oldlist[i]
                    : null;

                Boolean qualifiedBefore = oldOpp != null && isMajorGift(oldOpp);

                // "Updated so that it BECOMES Closed Won with Amount >= 5000
                //  when it was NOT both of those before."
                // Editing a gift that already qualified does not re-trigger.
                shouldCreate = qualifiesNow && !qualifiedBefore;
            }
            // Any other Action (afterDelete, beforeX, etc.) is not this
            // handler's concern; the dispatcher only routes the registered
            // actions here anyway.

            if (shouldCreate) {
                tasksToCreate.add(buildTask(newOpp));
            }
        }

        if (!tasksToCreate.isEmpty()) {
            if (wrapper == null) {
                wrapper = new npsp.TDTM_Runnable.dmlWrapper();
            }
            wrapper.wrappedDml.addAll(tasksToCreate); // 1 DML statement of our own
        }

        // Returning null is the correct no-op: the dispatcher only performs
        // DML when the returned DmlWrapper is non-null.
        return wrapper;
    }

    /** Core qualification: Closed Won with Amount >= 5000. */
    private Boolean isMajorGift(Opportunity opp) {
        return opp.IsWon == true
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    /** Builds the follow-up Task for one qualifying Opportunity. */
    private Task buildTask(Opportunity opp) {
        Task t = new Task(
            Subject  = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status   = TASK_STATUS,
            WhatId   = opp.Id,
            OwnerId  = opp.OwnerId
        );

        // Primary contact may be null — in that case WhoId is simply left null.
        t.WhoId = opp.npsp__Primary_Contact__c;

        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(DAYS_AFTER_CLOSE);
        }

        return t;
    }
}
