// ---------------------------------------------------------------------------
// RecordAccessService
//
// Answers the question: which of these records can the running user edit?
//
// Uses the UserRecordAccess object, which is the platform's own access
// engine. One bulk query takes into account object permissions, ownership,
// sharing rules, the role hierarchy, View All, Modify All and Modify All
// Data. The result reflects any sharing or permission changes made earlier
// in the same transaction.
// ---------------------------------------------------------------------------
public with sharing class RecordAccessService {

    // Maximum number of ids bound into a single UserRecordAccess query.
    // The governor limit for items in an IN clause is 4000, so 2000 keeps
    // headroom while guaranteeing that the documented input size of 2000
    // ids resolves in exactly one SOQL query. Any larger input (defensive
    // only) is split across multiple queries rather than dropped.
    private static final Integer QUERY_CHUNK_SIZE = 2000;

    // Maximum number of SOQL queries the method is allowed to spend.
    // Kept as a named constant for clarity and future tuning.
    // 2000 ids at QUERY_CHUNK_SIZE 2000 needs exactly one query.
    private static final Integer MAX_SOQL_QUERIES = 20;

    /**
     * Returns the subset of recordIds that the running user can edit,
     * as reported by UserRecordAccess.HasEditAccess.
     *
     * Records that do not exist or are not visible to the running user
     * produce no row with HasEditAccess true and are therefore excluded,
     * which is the correct and secure behavior for a mass edit screen.
     *
     * @param recordIds candidate record ids across any object; may be null,
     *                  empty, or contain null elements
     * @return the editable subset; never null; never contains null ids
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        // Null or empty input returns an empty set, never null.
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Sanitize and deduplicate the input: drop null elements and work on
        // a copy so the caller's set is never mutated. Apex normalizes
        // 15 character id forms to 18 characters on assignment, so plain
        // set semantics already handle 15 versus 18 character duplicates.
        Set<Id> sanitizedIds = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                sanitizedIds.add(recordId);
            }
        }

        if (sanitizedIds.isEmpty()) {
            return result;
        }

        // Query the access engine in chunks. For the contracted input of
        // 2000 ids this is exactly one SOQL query, well within budget.
        // UserId plus RecordId is the required filter combination for
        // UserRecordAccess. The result reflects the current transaction.
        List<List<Id>> chunks = splitIntoChunks(sanitizedIds, QUERY_CHUNK_SIZE);
        Integer queriesUsed = 0;

        for (List<Id> chunk : chunks) {
            if (queriesUsed >= MAX_SOQL_QUERIES) {
                // Hard safety net for grossly oversized input.
                break;
            }
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
            ]) {
                // Check again in Apex for belt and braces. Only ids from the
                // input can appear here because of the RecordId IN filter.
                if (access.HasEditAccess == true) {
                    result.add(access.RecordId);
                }
            }
            queriesUsed++;
        }

        return result;
    }

    /**
     * Splits a set of ids into chunks of at most chunkSize elements each.
     *
     * @param ids       sanitized, non null input ids
     * @param chunkSize maximum number of elements per chunk; must be positive
     * @return list of chunks; never null
     */
    private static List<List<Id>> splitIntoChunks(Set<Id> ids, Integer chunkSize) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> currentChunk = new List<Id>();

        for (Id recordId : ids) {
            currentChunk.add(recordId);
            if (currentChunk.size() >= chunkSize) {
                chunks.add(currentChunk);
                currentChunk = new List<Id>();
            }
        }
        if (!currentChunk.isEmpty()) {
            chunks.add(currentChunk);
        }
        return chunks;
    }
}
