        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Drop null elements and work on a copy. Apex normalizes
        // 15 character id forms to 18 characters on assignment, so
        // set semantics already handle 15 versus 18 duplicates.
        Set<Id> sanitizedIds = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                sanitizedIds.add(recordId);
            }
        }

        if (sanitizedIds.isEmpty()) {
            return result;
        }

        // Query the access engine in chunks. For the contracted
        // input of 2000 ids this is exactly one SOQL query. UserId
        // plus RecordId is the required filter combination for
        // UserRecordAccess.
        List<List<Id>> chunks = splitIntoChunks(sanitizedIds, QUERY_CHUNK_SIZE);
        Integer queriesUsed = 0;

        for (List<Id> chunk : chunks) {
            if (queriesUsed >= MAX_SOQL_QUERIES) {
                // Safety net for grossly oversized input.
                break;
            }
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
            ]) {
                // Filter again in Apex for belt and braces. Only ids
                // from the input can appear here because of the
                // RecordId IN filter.
                if (access.HasEditAccess) {
                    result.add(access.RecordId);
                }
            }
            queriesUsed++;
        }

        return result;
    }

    // Splits a set of ids into chunks of at most chunkSize elements
    // each. Returns a list of chunks, never null.
    private static List<List<Id>> splitIntoChunks(Set<Id> ids, Integer chunkSize) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> currentChunk = new List<Id>();

        for (Id recordId : ids) {
            currentChunk.add(recordId);
            if (currentChunk.size() >= chunkSize) {
                chunks.add(currentChunk);
                currentChunk = new List<Id>();
            }
        }
        if (!currentChunk.isEmpty()) {
            chunks.add(currentChunk);
        }
        return chunks;
    }
}
```

