/**
 * @description Service for migrating contacts from the legacy system.
 *
 * Inserted contacts must go through all normal Contact trigger automation except
 * TA_Contact_CreateWelcomeTask, because migrated contacts are existing customers who
 * must not receive a "Send welcome pack" Task. Phone formatting
 * (TA_Contact_FormatPhone, before insert) must still run, so the Contact-level bypass
 * (TriggerAction.TriggerBase.bypass) must NOT be used — that would skip the phone
 * formatting action too. Instead, only the specific after-insert action is bypassed
 * via the handler-level bypass API (TriggerAction.Handler).
 *
 * The bypass is scoped to the single DML statement in this method and is always
 * cleared before the method returns, even if the insert throws. Contacts inserted
 * later in the same transaction therefore get their welcome task as usual.
 */
public inherited sharing class ContactImportService {

    /** API name of the TAF action to skip for imported (existing-customer) contacts. */
    @TestVisible
    private static final String WELCOME_TASK_ACTION_NAME = 'TA_Contact_CreateWelcomeTask';

    /**
     * @description Inserts the given contacts in one DML statement with
     *              TA_Contact_CreateWelcomeTask skipped; all other Contact automation
     *              (including TA_Contact_FormatPhone) still runs.
     * @param contacts Contacts to insert. May be null or empty; nothing happens.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Skip only the welcome-task action for this import.
        // Scope (String) form: skips that action regardless of which handler
        // implementation/flow wraps it; uses the action's API name, which is stable.
        TriggerAction.Handler.bypass(WELCOME_TASK_ACTION_NAME);

        try {
            // Single DML statement; TAF's after-insert logic fires for every other
            // action, and the welcome-task action sees the bypass and does nothing.
            insert contacts;
        } finally {
            // Always restore the previous state, even if the insert fails, so that
            // contacts inserted later in this transaction get their welcome task.
            TriggerAction.Handler.clearBypass(WELCOME_TASK_ACTION_NAME);
        }
    }
}
