/**
 * Contact before-insert action: when a new contact has an Account and a blank
 * LeadSource, default it to the account's AccountSource. Contacts without an
 * Account are left alone.
 *
 * Relies on TA_Contact_Queries.Service (Order__c = 1) having loaded the parent
 * accounts, so this action performs no SOQL of its own.
 */
public with sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {

	public void beforeInsert(List<SObject> triggerNew) {
		Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
		for (Contact contact : (List<Contact>) triggerNew) {
			if (contact.AccountId == null) {
				continue;
			}
			if (contact.LeadSource != null) {
				continue;
			}
			Account account = accountsById.get(contact.AccountId);
			if (account == null) {
				continue;
			}
			contact.LeadSource = account.AccountSource;
		}
	}
}
